(window.MAP_DATA = window.MAP_DATA || {})["reading_3"] = {"grade":3,"subject":"reading","units":[{"id":"U1","title":"Who, Where and What Happened?","goal":"LT","band":"151–170","skills":["Find the characters and the setting of a story","Find details about events","Put events in order (beginning, middle, end)","Tell how a character feels and why"],"vocab":[["kite","a toy that flies in the wind on a long string"],["string","a thin rope"],["stuck","not able to move"],["branch","an arm of a tree"],["ladder","steps you climb to reach high places"],["thank","to say you are happy someone helped you"]],"sets":[{"set":"A","passage":{"title":"Sami's Red Kite","genre":"story","paras":["It was a windy day in the park. Sami had a new red kite. He ran fast, and the kite went up, up, up into the sky.","Then the wind blew hard. The kite flew into a tall tree. The string was stuck on a high branch. Sami pulled, but the kite did not move. Sami was sad. He sat down under the tree.","Sami’s grandfather saw the kite. He went to his car and came back with a small ladder. He climbed up slowly and pulled the string free. The red kite fell into Sami’s hands.","“Thank you, Grandpa!” Sami said with a big smile. This time, Sami flew his kite far away from the trees."]},"items":[{"n":1,"t":"mc","s":"Where does the story happen?","o":["at a school","in a market","at the beach","in a park"],"k":"D","sk":"Identifies setting","b":"161–170","g":"LT"},{"n":2,"t":"mc","s":"Who helps Sami get his kite back?","o":["his grandfather","his teacher at school","his sister","his friend"],"k":"A","sk":"Locates details about characters","b":"161–170","g":"LT"},{"n":3,"t":"mc","s":"What happens FIRST in the story?","o":["The kite flies into a tree.","Grandpa climbs a ladder.","Sami runs, and the kite goes up.","Sami says “Thank you, Grandpa!”"],"k":"C","sk":"Understands sequence in literary text","b":"161–170","g":"LT"},{"n":4,"t":"mc","s":"Why is Sami sad?","o":["His grandfather goes home.","His kite is stuck in a tree.","The wind stops.","His kite is broken."],"k":"B","sk":"Infers character feelings and why","b":"161–170","g":"LT"},{"n":5,"t":"mc","s":"What does Sami do at the END of the story?","o":["He flies his kite far away from the trees.","He climbs the tall tree.","He buys a new kite.","He goes home with his grandfather to get a ladder."],"k":"A","sk":"Locates details about events","b":"161–170","g":"LT"},{"n":6,"t":"tp","s":"Part A: How does Sami feel at the end of the story?","o":["tired","scared","angry","happy"],"k":"D","sk":"Infers character feelings; finds evidence","b":"171–180","g":"LT","pb":{"s":"Which words from the story show the answer to Part A?","o":["“The wind blew hard.”","“Sami pulled”","“with a big smile”","“He sat down under the tree.”"],"k":"C"}}]},{"set":"B","passage":{"title":"The Ball on the Roof","genre":"story","paras":["After school, Hadi and his friend Ziyad played football in the yard. Ziyad kicked the ball very hard. It flew up and landed on the roof of the house.","“Oh no!” said Hadi. “That is my only ball.” The boys looked up. The roof was too high to climb.","Then Hadi had an idea. He turned on the water hose and sprayed water onto the roof. The water pushed the ball, and it rolled down into the yard.","The boys cheered. “You are smart, Hadi!” said Ziyad. Then they played again, but this time they kicked the ball softly."]},"items":[{"n":1,"t":"mc","s":"Where are the boys playing?","o":["at school","in the yard","in the park","on the roof"],"k":"B","sk":"Identifies setting","b":"161–170","g":"LT"},{"n":2,"t":"mc","s":"What happens to the ball?","o":["It breaks.","It falls into a pool.","It lands on the roof.","It goes into the street."],"k":"C","sk":"Locates details about events","b":"161–170","g":"LT"},{"n":3,"t":"mc","s":"What happens LAST in the story?","o":["The boys play again and kick softly.","Ziyad kicks the ball very hard again.","Hadi turns on the hose.","The ball lands on the roof again."],"k":"A","sk":"Understands sequence in literary text","b":"161–170","g":"LT"},{"n":4,"t":"mc","s":"Why can the boys not get the ball easily?","o":["It is too dark.","The ball is too heavy to throw down.","Hadi’s father is angry.","The roof is too high to climb."],"k":"D","sk":"Identifies conflict in literary text","b":"171–180","g":"LT"},{"n":5,"t":"mc","s":"How does Hadi get the ball back?","o":["He throws a small stone at the ball.","He asks his father.","He climbs a ladder up to the roof.","He sprays water to push the ball down."],"k":"D","sk":"Identifies resolution","b":"171–180","g":"LT"},{"n":6,"t":"mc","s":"What does Ziyad think of Hadi’s idea?","o":["He does not like it.","He thinks it is smart.","He thinks it is dangerous.","He thinks it is silly."],"k":"B","sk":"Infers character thoughts","b":"171–180","g":"LT"},{"n":7,"t":"mc","s":"Why do the boys kick the ball softly at the end?","o":["Their teacher told them to kick very softly.","They are too tired to kick it hard.","They do not want it to go on the roof again.","The ball is broken."],"k":"C","sk":"Explains character motivation","b":"181–190","g":"LT"}]}]},{"id":"U2","title":"What Is It Mostly About?","goal":"IT","band":"151–170","skills":["Find the main idea of a short text","Find key details","Use headings, pictures and captions","Learn topic words from the text"],"vocab":[["desert","a dry place with little rain"],["hump","the big round part on a camel’s back"],["fat","food the body keeps to use later"],["eyelashes","little hairs around the eyes"],["sand","very small pieces of rock"],["travel","to go from one place to another"]],"sets":[{"set":"A","passage":{"title":"Camels in the Desert","genre":"informational","paras":["**Made for the Desert**","Camels live in hot, dry deserts. Their bodies help them live where there is little food and water.","**The Hump**","A camel’s hump does not hold water. It holds fat. When there is no food, the camel’s body uses the fat. A camel can walk for many days without eating.","**Eyes and Feet**","Camels have long eyelashes. The eyelashes keep sand out of their eyes. Camels also have big, wide feet. Wide feet help them walk on soft sand without sinking.","*Picture caption: A camel’s wide feet help it walk on sand.*"]},"items":[{"n":1,"t":"mc","s":"What does a camel’s hump hold?","o":["water","fat","milk","sand"],"k":"B","sk":"Locates details in informational text","b":"161–170","g":"IT"},{"n":2,"t":"mc","s":"Why do camels have long eyelashes?","o":["to keep sand out of their eyes","to keep them cool","to help them see at night in the dark","to help them find water"],"k":"A","sk":"Understands explicit relationships between ideas","b":"161–170","g":"IT"},{"n":3,"t":"mc","s":"Under which heading can you read about a camel’s feet?","o":["The Hump","Made for the Desert","Eyes and Feet","Camels in the Desert"],"k":"C","sk":"Uses headings to locate information","b":"161–170","g":"IT"},{"n":4,"t":"mc","s":"What does the picture caption tell the reader?","o":["Deserts are hot and dry.","A camel’s hump holds fat.","Camels can walk for many days without food.","Wide feet help a camel walk on sand."],"k":"D","sk":"Integrates information from graphics and text","b":"161–170","g":"IT"},{"n":5,"t":"mc","s":"What is this text mostly about?","o":["how people ride camels in races","how camels can live in the desert","why deserts are hot","what camels like to eat for dinner"],"k":"B","sk":"Determines main idea in informational text","b":"171–180","g":"IT"},{"n":6,"t":"ms","s":"Which TWO body parts help a camel live in the desert? Choose TWO answers.","o":["its sharp teeth","its small ears","its hump","its wide feet","its short tail"],"k":"C, D","sk":"Locates key details","b":"171–180","g":"IT"}]},{"set":"B","passage":{"title":"Owls at Night","genre":"informational","paras":["**Night Birds**","Owls are birds that hunt at night. They sleep in the day and wake up when it gets dark.","**Big Eyes**","Owls have very big eyes. Their eyes help them see in the dark.","**Quiet Wings**","An owl’s feathers are soft. Soft feathers make its wings very quiet, so mice do not hear the owl coming.","*Caption: An owl can turn its head far around to look behind it.*"]},"items":[{"n":1,"t":"mc","s":"When do owls hunt?","o":["at lunchtime","after rain","in the morning","at night"],"k":"D","sk":"Locates details in informational text","b":"161–170","g":"IT"},{"n":2,"t":"mc","s":"Under which heading can you read about an owl’s eyes?","o":["Big Eyes","Night Birds","Quiet Wings","Owls at Night"],"k":"A","sk":"Uses headings to locate information","b":"161–170","g":"IT"},{"n":3,"t":"mc","s":"What does the caption tell you?","o":["Owls eat mice.","An owl can turn its head far around.","Owls sleep in the day and hunt at night.","Owls have soft feathers."],"k":"B","sk":"Integrates information from graphics and text","b":"161–170","g":"IT"},{"n":4,"t":"mc","s":"What is this text mostly about?","o":["where birds sleep in winter","why mice are small","how owls hunt at night","how to feed birds"],"k":"C","sk":"Determines main idea in informational text","b":"171–180","g":"IT"},{"n":5,"t":"mc","s":"Why are an owl’s wings quiet?","o":["Its eyes are big.","It is very small.","It sleeps in the day.","Its feathers are soft."],"k":"D","sk":"Understands explicit relationships between ideas","b":"171–180","g":"IT"},{"n":6,"t":"ms","s":"Which TWO things help an owl hunt? Choose TWO answers.","o":["bright colors","big eyes","a long tail","quiet wings","a loud call"],"k":"B, D","sk":"Locates key details","b":"171–180","g":"IT"},{"n":7,"t":"mc","s":"Why do mice not hear the owl coming?","o":["The mice are sleeping.","The owl is very far away from the mice.","The owl’s wings are very quiet.","The mice have small ears."],"k":"C","sk":"Determines the cause of a situation","b":"181–190","g":"IT"}]}]},{"id":"U3","title":"Word Detectives","goal":"VO","band":"151–180","skills":["Use the words around a new word (context clues)","Prefixes un- and re-","Suffixes -ful and -less","Compound words","Words with the same meaning (synonyms) and opposite meaning (antonyms)"],"vocab":[["unhappy","not happy"],["reread","read again"],["helpful","full of help; giving help"],["careless","without care"],["sunshine","sun + shine: the light from the sun"],["huge","very big"]],"sets":[{"set":"A","passage":{"title":"Word Clues","genre":"sentences","paras":["A **prefix** comes at the beginning of a word. **un-** means *not*: unhappy = not happy. **re-** means *again*: redo = do again.","A **suffix** comes at the end of a word. **-ful** means *full of*: helpful. **-less** means *without*: careless.","A **compound word** is two small words put together: rain + coat = raincoat.","**Context clues** are words near a new word that help you understand it."]},"items":[{"n":1,"t":"mc","s":"Read the sentence. “The door was **unlocked**, so we walked right in.” What does **unlocked** mean?","o":["not locked","easy to lock","locked well","locked again"],"k":"A","sk":"Understands how the prefix un- changes meaning","b":"151–160","g":"VO"},{"n":2,"t":"mc","s":"Mona wrote her story again because it was messy. She had to ___ her story.","o":["writeful","writeless","unwrite","rewrite"],"k":"D","sk":"Understands how the prefix re- changes meaning","b":"151–160","g":"VO"},{"n":3,"t":"mc","s":"Read the sentence. “The elephant was **huge**; it was bigger than our car.” Which word means the same as **huge**?","o":["very small","very fast","very big","very old"],"k":"C","sk":"Uses context to determine word meaning","b":"161–170","g":"VO"},{"n":4,"t":"mc","s":"Which word means the OPPOSITE of **hot**?","o":["sunny","cold","warm","wet"],"k":"B","sk":"Identifies antonyms","b":"161–170","g":"VO"},{"n":5,"t":"mc","s":"Which word means “without fear”?","o":["fearful","fearless","refear","unfear"],"k":"B","sk":"Understands how the suffix -less changes meaning","b":"171–180","g":"VO"},{"n":6,"t":"mc","s":"Which word is a compound word?","o":["running","teacher","happy","football"],"k":"D","sk":"Understands compound words","b":"171–180","g":"VO"}]},{"set":"B","passage":null,"items":[{"n":1,"t":"mc","s":"Which word means “not safe”?","o":["safeless","resafe","safeful","unsafe"],"k":"D","sk":"Understands how the prefix un- changes meaning","b":"151–160","g":"VO"},{"n":2,"t":"mc","s":"Read the sentence. “I will **refill** my water bottle.” What does **refill** mean?","o":["fill again","not fill","fill a little","fill wrongly"],"k":"A","sk":"Understands how the prefix re- changes meaning","b":"151–160","g":"VO"},{"n":3,"t":"mc","s":"Read the sentence. “The baby was **sleepy**, so he closed his eyes.” What does **sleepy** mean?","o":["happy and ready to play","very loud","tired and ready to sleep","hungry and ready to eat"],"k":"C","sk":"Uses context to determine word meaning","b":"161–170","g":"VO"},{"n":4,"t":"mc","s":"Which word means the OPPOSITE of **fast**?","o":["early","slow","strong","quick"],"k":"B","sk":"Identifies antonyms","b":"161–170","g":"VO"},{"n":5,"t":"mc","s":"A **joyful** song is a song that is —","o":["full of joy","sung again","very quiet","without joy"],"k":"A","sk":"Understands how the suffix -ful changes meaning","b":"171–180","g":"VO"},{"n":6,"t":"mc","s":"Which word is made of two smaller words?","o":["rained","raincoat","rainy","raining"],"k":"B","sk":"Understands compound words","b":"171–180","g":"VO"},{"n":7,"t":"mc","s":"Which word means almost the same as **shout**?","o":["sing","whisper","listen","yell"],"k":"D","sk":"Identifies synonyms","b":"171–180","g":"VO"}]}]},{"id":"U4","title":"Lessons in Stories","goal":"LT","band":"161–180","skills":["Find the lesson (moral) of a fable","Explain why a character does something","Understand comparisons with “like” or “as” (similes)","Choose the best title"],"vocab":[["turtle","an animal with a hard shell"],["shade","a cool, dark place out of the sun"],["proud","feeling that you are better than others"],["share","to let others use what you have"],["rest","to stop and relax"],["kind","nice and helpful to others"]],"sets":[{"set":"A","passage":{"title":"The Turtle and the Shade","genre":"fable","paras":["One hot day, a little turtle found a big rock. The rock made a cool shade, and the turtle rested under it.","A rabbit came by. “Please may I rest in the shade too?” asked the rabbit. The sun was as hot as an oven.","The turtle was proud. “No! This is my shade,” he said. The rabbit hopped away slowly.","Later, the sun moved. The shade moved to the other side of the rock, and the turtle was in the hot sun. He was too slow to move fast. The rabbit came back and pushed a big leaf over him to keep him cool.","“You are kind,” said the turtle. “I am sorry I did not share.” From that day, the turtle always shared his shade."]},"items":[{"n":1,"t":"mc","s":"Why does the turtle say “No!” to the rabbit?","o":["He is afraid of the big rabbit.","The shade is too small for the two of them.","He is going to sleep.","He is proud and wants the shade for himself."],"k":"D","sk":"Explains character motivation","b":"161–170","g":"LT"},{"n":2,"t":"mc","s":"What does the rabbit do to help the turtle?","o":["He gives him water.","He pushes a big leaf over him.","He carries the turtle to the sea.","He moves the big rock away."],"k":"B","sk":"Locates details about events","b":"161–170","g":"LT"},{"n":3,"t":"mc","s":"What lesson does the turtle learn?","o":["Rabbits are faster than turtles.","You should rest every day.","It is good to share with others.","Rocks are better than trees."],"k":"C","sk":"Determines the moral of a fable","b":"171–180","g":"LT"},{"n":4,"t":"mc","s":"The text says the sun was “as hot as an oven.” What does this mean?","o":["The sun was very hot.","The sun was behind the rock.","The sun was cooking food.","The sun was going down."],"k":"A","sk":"Interprets simile in context","b":"171–180","g":"LT"},{"n":5,"t":"mc","s":"How does the turtle change from the beginning to the end?","o":["He is hungry at first and full at the end.","He is fast at first and slow at the end.","He is happy at first and sad at the end.","He is selfish at first and kind at the end."],"k":"D","sk":"Understands how characters change","b":"181–190","g":"LT"},{"n":6,"t":"mc","s":"Which is the BEST new title for the story?","o":["The Fastest Animal in the Field","A Day at the Beach","A Kind Rabbit Teaches a Lesson","How Turtles Grow Big and Strong"],"k":"C","sk":"Identifies the best title for a literary text","b":"181–190","g":"LT"}]},{"set":"B","passage":{"title":"The Ant and the Big Rain","genre":"fable","paras":["All summer, a little ant carried seeds into her home. A grasshopper laughed at her. “Why work so hard? Come and sing with me!”","“The rain will come soon,” said the ant. “I must be ready.” The grasshopper only sang louder.","One day, dark clouds filled the sky, and the big rain came. The fields were as wet as a lake. The grasshopper had no food and no dry place to stay.","The ant opened her door. “Come in,” she said. “Next summer, we will work together.” The grasshopper nodded. He had learned his lesson."]},"items":[{"n":1,"t":"mc","s":"What does the ant do all summer?","o":["She carries seeds to her home.","She plays in the rain all day with her friends.","She sings songs.","She sleeps."],"k":"A","sk":"Locates details about characters","b":"161–170","g":"LT"},{"n":2,"t":"mc","s":"How does the ant help the grasshopper?","o":["She gives him an umbrella to keep him dry.","She builds him a house.","She sings with him.","She lets him come into her home."],"k":"D","sk":"Locates details about events","b":"161–170","g":"LT"},{"n":3,"t":"mc","s":"Why does the ant work so hard?","o":["She wants to sing.","She wants to be ready for the rain.","She wants to win a race.","She is angry with the grasshopper."],"k":"B","sk":"Explains character motivation","b":"171–180","g":"LT"},{"n":4,"t":"mc","s":"“The fields were as wet as a lake.” What does this mean?","o":["The fields were green and full of grass.","The fields had fish.","The fields were very wet.","The fields were dry."],"k":"C","sk":"Interprets simile in context","b":"171–180","g":"LT"},{"n":5,"t":"mc","s":"What problem does the grasshopper have when the rain comes?","o":["He is too hot.","He cannot find the ant’s house.","He has no food and no dry place.","He loses his voice from singing."],"k":"C","sk":"Identifies conflict in literary text","b":"171–180","g":"LT"},{"n":6,"t":"mc","s":"What lesson does the grasshopper learn?","o":["Rain is fun.","Singing is better than working all day.","Ants are bigger and stronger than grasshoppers.","It is wise to work and get ready for the future."],"k":"D","sk":"Determines the moral of a fable","b":"181–190","g":"LT"},{"n":7,"t":"mc","s":"How does the grasshopper change?","o":["He becomes bigger.","He stops laughing at work and wants to help.","He moves to a new field far away.","He becomes a better and much louder singer."],"k":"B","sk":"Understands how characters change","b":"181–190","g":"LT"}]}]},{"id":"U5","title":"Steps, Causes and Charts","goal":"IT","band":"161–180","skills":["Follow steps in order (sequence)","Find causes and effects (why something happens)","Read a simple chart","Tell the author’s purpose"],"vocab":[["seed","the small part of a plant that grows into a new plant"],["soil","dirt that plants grow in"],["cup","a small open container"],["sprout","a new, small plant"],["sunlight","light from the sun"],["measure","to find out how big or long something is"]],"sets":[{"set":"A","passage":{"title":"Grow a Bean Plant","genre":"how-to","paras":["You can grow a bean plant in your classroom. Here is how.","1. Fill a cup with soil.","2. Push a bean seed into the soil with your finger.","3. Give the seed a little water.","4. Put the cup near a sunny window. Plants need sunlight to grow.","After about five days, a small green sprout will come up. Measure your plant every day.","**Our Bean Plant Chart** — Day 5: 1 cm · Day 7: 3 cm · Day 9: 6 cm · Day 11: 9 cm"]},"items":[{"n":1,"t":"mc","s":"Look at the chart. How tall was the plant on Day 9?","o":["3 cm","6 cm","9 cm","1 cm"],"k":"B","sk":"Interprets information in charts","b":"161–170","g":"IT"},{"n":2,"t":"mc","s":"What should you do FIRST?","o":["Give the seed water.","Put the cup near a window.","Fill a cup with soil.","Measure the plant."],"k":"C","sk":"Understands sequence in informational text","b":"171–180","g":"IT"},{"n":3,"t":"mc","s":"What does the chart show?","o":["The plant grew taller every two days.","The plant was tallest on Day 5 of the chart.","The plant needed no water.","The plant stopped growing."],"k":"A","sk":"Interprets information in charts","b":"171–180","g":"IT"},{"n":4,"t":"mc","s":"What is the author’s main purpose?","o":["to tell a funny story about beans","to describe a garden in the spring","to make you buy beans","to teach how to grow a bean plant"],"k":"D","sk":"Determines specific purpose of an informational text","b":"171–180","g":"IT"},{"n":5,"t":"mc","s":"Why should you put the cup near a sunny window?","o":["Plants need sunlight to grow.","The cup will not fall.","The seed will stay cold.","The window keeps the soil dry."],"k":"A","sk":"Determines the cause of an event","b":"181–190","g":"IT"},{"n":6,"t":"mc","s":"Why does the author use numbers 1, 2, 3 and 4?","o":["to count the seeds","to show the days of the week","to show the steps in order","to show how tall the plant is"],"k":"C","sk":"Determines the purpose of a text feature","b":"181–190","g":"IT"}]},{"set":"B","passage":{"title":"Make Fresh Lemon Juice","genre":"how-to","paras":["Fresh lemon juice is easy to make. Ask an adult to help you with the knife.","1. Wash three lemons.","2. Cut each lemon in half.","3. Squeeze the juice into a jug.","4. Add four cups of cold water and a little sugar.","5. Stir well and serve.","**How many cups can you serve?** — 3 lemons: 4 cups · 6 lemons: 8 cups · 9 lemons: 12 cups"]},"items":[{"n":1,"t":"mc","s":"What should you do FIRST?","o":["Cut each lemon in half.","Wash three lemons.","Add cold water.","Stir well."],"k":"B","sk":"Understands sequence in informational text","b":"171–180","g":"IT"},{"n":2,"t":"mc","s":"What do you do right after you cut the lemons?","o":["Wash the lemons in cold water.","Add sugar and stir it well.","Squeeze the juice into a jug.","Serve the juice."],"k":"C","sk":"Understands sequence in informational text","b":"171–180","g":"IT"},{"n":3,"t":"mc","s":"Look at the list. How many cups can you serve with 6 lemons?","o":["8 cups","12 cups","6 cups","4 cups"],"k":"A","sk":"Interprets information in charts","b":"171–180","g":"IT"},{"n":4,"t":"mc","s":"What is the author’s purpose?","o":["to make you laugh","to describe a farm","to tell a story about a lemon tree","to teach how to make lemon juice"],"k":"D","sk":"Determines specific purpose of an informational text","b":"171–180","g":"IT"},{"n":5,"t":"mc","s":"Why should an adult help?","o":["to drink the juice","to buy more lemons at the shop","to wash the jug","to help with the knife"],"k":"D","sk":"Determines the cause of a situation","b":"181–190","g":"IT"},{"n":6,"t":"mc","s":"What do you need to make 12 cups?","o":["6 lemons","12 lemons","9 lemons","3 lemons"],"k":"C","sk":"Interprets information in charts","b":"181–190","g":"IT"},{"n":7,"t":"mc","s":"Why are the steps numbered?","o":["to count how many lemons you need","to show the order of the steps","to show the price","to show how many cups to use"],"k":"B","sk":"Determines the purpose of a text feature","b":"181–190","g":"IT"}]}]},{"id":"U6","title":"Two Texts, One Topic","goal":"Mixed","band":"171–190","skills":["Compare a story and a fact text on the same topic","Find what is the same and what is different","Retell a text in a short summary"],"vocab":[["sea turtle","a turtle that lives in the sea"],["nest","a home made for eggs"],["hatch","to come out of an egg"],["shore","the land next to the sea"],["protect","to keep safe"],["crawl","to move slowly on the ground"]],"sets":[{"set":"A","passage":{"title":"Text 1: Night on the Beach · Text 2: Baby Sea Turtles","genre":"paired","paras":["**Text 1: Night on the Beach (a story)**","Ali and his father walked on the beach at night. They saw tiny sea turtles crawl out of the sand. “Shh,” said Father. “Let them go to the sea.” Ali watched the babies walk to the waves. He felt happy that they were safe.","**Text 2: Baby Sea Turtles (facts)**","A mother sea turtle digs a nest on the shore and lays her eggs in it. After about two months, the baby turtles hatch. They usually come out at night, when it is cool. The babies crawl to the sea. People can protect them by keeping beaches clean and dark."]},"items":[{"n":1,"t":"mc","s":"In Text 2, when do baby sea turtles usually come out?","o":["after it rains","at night","at noon","in the morning"],"k":"B","sk":"Locates details in informational text","b":"161–170","g":"Literary and Informational Text (paired)"},{"n":2,"t":"mc","s":"Which text is a story?","o":["both texts","neither text","Text 2","Text 1"],"k":"D","sk":"Understands characteristics of fiction","b":"171–180","g":"Literary and Informational Text (paired)"},{"n":3,"t":"mc","s":"Text 2 says that baby turtles **hatch**. What does **hatch** mean?","o":["come out of an egg","dig deep holes in the sand","go to sleep","swim very fast"],"k":"A","sk":"Determines the meaning of domain-specific words","b":"171–180","g":"Literary and Informational Text (paired)"},{"n":4,"t":"mc","s":"What is the same in Text 1 and Text 2?","o":["Both tell how to dig a nest in the sand for eggs.","Both are made-up stories about animals.","Both tell about baby sea turtles going to the sea.","Both happen in the morning."],"k":"C","sk":"Compares and contrasts details in multiple texts","b":"181–190","g":"Literary and Informational Text (paired)"},{"n":5,"t":"mc","s":"Why does Father say “Shh” in Text 1?","o":["He is tired.","He is afraid of the big, dark sea at night.","He wants to let the turtles go to the sea safely.","He wants Ali to sleep on the warm sand."],"k":"C","sk":"Explains character motivation","b":"181–190","g":"Literary and Informational Text (paired)"},{"n":6,"t":"mc","s":"Which sentence is the BEST short summary of Text 2?","o":["Sea turtle eggs hatch on the shore, and the babies crawl to the sea.","Ali walks on the beach at night with his father, and they see the moon.","The beach is dark at night.","Sea turtles are big animals that swim very far."],"k":"A","sk":"Summarizes informational text","b":"181–190","g":"Literary and Informational Text (paired)"}]},{"set":"B","passage":{"title":"Text 1: Grandpa’s Garden · Text 2: Plants Need Water","genre":"paired","paras":["**Text 1: Grandpa’s Garden (a story)**","Every evening, Majid helped Grandpa water the tomato plants. One week, Majid forgot. The leaves turned yellow and hung down. Majid felt sorry. He gave the plants water every day after that, and soon they were green again.","**Text 2: Plants Need Water (facts)**","Plants need water to live. Water travels from the roots up to the leaves. When a plant does not get enough water, its leaves can turn yellow and droop. Most garden plants need water every day in hot weather."]},"items":[{"n":1,"t":"mc","s":"Which text gives facts?","o":["Text 1","neither text","Text 2","both texts"],"k":"C","sk":"Understands characteristics of fiction and nonfiction","b":"171–180","g":"Literary and Informational Text (paired)"},{"n":2,"t":"mc","s":"How does Majid feel when he sees the yellow leaves?","o":["proud","sorry","angry","excited"],"k":"B","sk":"Infers character feelings","b":"171–180","g":"Literary and Informational Text (paired)"},{"n":3,"t":"mc","s":"What is the same in Text 1 and Text 2?","o":["Both show that plants need water.","Both are made-up stories.","Both are about Grandpa.","Both tell how to cook tomatoes."],"k":"A","sk":"Compares and contrasts multiple texts","b":"181–190","g":"Literary and Informational Text (paired)"},{"n":4,"t":"mc","s":"In Text 1, why do the leaves turn yellow?","o":["It rained too much in the garden.","The sun went away.","Grandpa cut the leaves with scissors.","Majid forgot to water the plants."],"k":"D","sk":"Determines the cause of a situation","b":"181–190","g":"Literary and Informational Text (paired)"},{"n":5,"t":"mc","s":"In Text 2, what does **droop** mean?","o":["grow tall","smell nice","hang down","turn green"],"k":"C","sk":"Uses context to determine word meaning","b":"181–190","g":"Literary and Informational Text (paired)"},{"n":6,"t":"mc","s":"Which is the BEST summary of Text 1?","o":["Grandpa grows tomatoes in his garden, and Majid likes to eat them for lunch.","Majid plays in the garden every day after school with his friends.","Plants have roots.","Majid forgets to water the plants, they turn yellow, and he takes care of them again."],"k":"D","sk":"Summarizes literary text","b":"181–190","g":"Literary and Informational Text (paired)"},{"n":7,"t":"mc","s":"Which sentence from Text 2 explains what happened in Text 1?","o":["Most garden plants need water every day in hot weather.","When a plant does not get enough water, its leaves can turn yellow and droop.","Water travels from the roots up to the leaves.","Plants need water to live."],"k":"B","sk":"Synthesizes information from two texts","b":"191–200","g":"Literary and Informational Text (paired)"}]}]}],"mocks":[{"id":"A","note":"Full practice test · 43 questions","sections":[{"passage":{"title":"Omar's New Shoes","genre":"story","paras":["Omar got new running shoes for the school race. They were blue and white. He wore them every day after school to practise.","On the day of the race, Omar ran very fast. Near the end, his shoelace came open. Omar stopped to tie it. Two boys ran past him.","Omar finished third. At first he felt sad. Then his teacher said, “You ran your best, and you were safe. Next time, double-tie your laces!” Omar smiled. He knew what to do next time."]},"items":[{"n":1,"t":"mc","s":"Why did Omar wear his shoes every day after school?","o":["to go to the market","to play football","to show his friends his new shoes","to practise for the race"],"k":"D","sk":"Locates details about events","b":"161–170","g":"LT"},{"n":2,"t":"mc","s":"What problem does Omar have in the race?","o":["He is late for the race.","He loses his shoe.","His shoelace comes open.","He falls down."],"k":"C","sk":"Identifies conflict in literary text","b":"161–170","g":"LT"},{"n":3,"t":"mc","s":"How does Omar feel at FIRST when he finishes third?","o":["sleepy","sad","proud","angry"],"k":"B","sk":"Infers character feelings","b":"161–170","g":"LT"},{"n":4,"t":"mc","s":"What colors were Omar’s new shoes?","o":["blue and white","red and black","all white","green and yellow"],"k":"A","sk":"Locates details about characters","b":"161–170","g":"LT"},{"n":5,"t":"mc","s":"What will Omar MOST LIKELY do before the next race?","o":["buy new shiny red shoes for the race","double-tie his shoelaces","run more slowly","stay home"],"k":"B","sk":"Makes inferences from literary text","b":"171–180","g":"LT"}]},{"passage":{"title":"The Moon and the Lamp","genre":"poem","paras":["At night my room is dark and still,","The moon looks in above the hill.","Its glow is soft, just like a lamp,","It shines upon our desert camp.","","I say, “Good night, old silver friend,”","And wait to see the darkness end.","When morning comes, the moon goes away,","And golden sun brings a new day."],"poem":true},"items":[{"n":6,"t":"mc","s":"When is the speaker’s room dark and still?","o":["at noon","in the morning","after school","at night"],"k":"D","sk":"Locates details in poetry","b":"161–170","g":"LT"},{"n":7,"t":"mc","s":"What does the speaker call the moon?","o":["“our desert camp”","“golden sun”","“old silver friend”","“a new day”"],"k":"C","sk":"Locates details in poetry","b":"171–180","g":"LT"},{"n":8,"t":"mc","s":"The poem says the moon’s glow is soft, “just like a lamp.” What does this tell you?","o":["The moon gives a gentle light.","The moon is very hot.","The moon is a real lamp in the sky.","The moon is very loud."],"k":"A","sk":"Interprets simile in context","b":"171–180","g":"LT"},{"n":9,"t":"mc","s":"When does the moon go away in the poem?","o":["when the lamp is on","when the speaker sleeps","when it rains","when morning comes"],"k":"D","sk":"Understands sequence in literary text","b":"171–180","g":"LT"},{"n":10,"t":"mc","s":"How do you know this text is a poem?","o":["It has headings.","It has short lines that rhyme.","It gives steps in order, from first to last.","It has a chart."],"k":"B","sk":"Classifies literary text as poetry","b":"171–180","g":"LT"}]},{"passage":{"title":"Falcons","genre":"informational","paras":["A falcon is a fast bird. It has strong wings, a sharp beak and sharp claws called talons.","Falcons can see very well. A falcon flying high in the sky can see a small animal on the ground.","When a falcon dives down to catch food, it can fly faster than a car on a highway.","In Saudi Arabia, some people train falcons. The birds learn to fly back to their trainer’s arm."]},"items":[{"n":11,"t":"mc","s":"What are a falcon’s **talons**?","o":["sharp claws","small eyes","long feathers","strong wings"],"k":"A","sk":"Determines domain-specific word meaning in context","b":"161–170","g":"IT"},{"n":12,"t":"mc","s":"What do some people in Saudi Arabia do with falcons?","o":["sell them in shops","paint them","train them","keep them in school"],"k":"C","sk":"Locates details in informational text","b":"161–170","g":"IT"},{"n":13,"t":"mc","s":"What is this text mostly about?","o":["animals that live in the sea","how to build a nest","what falcons are like","how to drive a car"],"k":"C","sk":"Determines main idea in informational text","b":"171–180","g":"IT"},{"n":14,"t":"mc","s":"Which sentence shows that falcons can see well?","o":["The birds learn to fly back to their trainer’s arm.","A falcon is a fast bird.","When a falcon dives down to catch food, it can fly faster than a car on a highway.","A falcon flying high in the sky can see a small animal on the ground."],"k":"D","sk":"Identifies evidence that supports a statement","b":"171–180","g":"IT"},{"n":15,"t":"mc","s":"The author compares a diving falcon to a car to show that falcons are —","o":["very heavy","very fast","very big","very quiet"],"k":"B","sk":"Understands explicit relationships between ideas","b":"181–190","g":"IT"}]},{"passage":{"title":"Library Rules","genre":"sign","paras":["**Welcome to the School Library!**","1. Walk, do not run.","2. Use a quiet voice.","3. Wash your hands before you touch the books.","4. Return books after one week.","Open: Sunday to Thursday, 8:00 to 2:00"]},"items":[{"n":16,"t":"mc","s":"How long can you keep a library book?","o":["one week","one day","two weeks","one month"],"k":"A","sk":"Locates details in informational text","b":"161–170","g":"IT"},{"n":17,"t":"mc","s":"What should you do with a library book after one week?","o":["buy it","return it","keep it","give it to a friend"],"k":"B","sk":"Locates details in informational text","b":"161–170","g":"IT"},{"n":18,"t":"mc","s":"What is the main purpose of this sign?","o":["to tell a funny story about books","to describe a teacher","to tell students the library rules","to sell new books"],"k":"C","sk":"Determines specific purpose of a poster or sign","b":"171–180","g":"IT"},{"n":19,"t":"mc","s":"On which day is the library closed?","o":["Friday","Sunday","Thursday","Monday"],"k":"A","sk":"Locates information in a text feature","b":"181–190","g":"IT"},{"n":20,"t":"mc","s":"Why should students wash their hands before they touch the books?","o":["to find books more quickly","to be quiet","to read the books faster","to keep the books clean"],"k":"D","sk":"Determines the cause of a situation","b":"181–190","g":"IT"}]},{"passage":{"title":"The Lost Lunch Box","genre":"story","paras":["At lunchtime, Saud opened his bag. His lunch box was not there! His stomach made a loud noise.","His friend Bader saw his sad face. “You can have half of my sandwich,” he said. Saud smiled and said thank you.","After school, Saud found his lunch box on the kitchen table at home. The next day, he brought two oranges, one for himself and one for Bader."]},"items":[{"n":21,"t":"mc","s":"What is Saud’s problem?","o":["He does not have his lunch box.","He is late for school again today.","He lost his friend.","He is sick."],"k":"A","sk":"Identifies conflict in literary text","b":"161–170","g":"LT"},{"n":22,"t":"mc","s":"How does Bader help Saud?","o":["He finds Saud’s lunch box.","He gives him half of his sandwich.","He buys him a cold drink from the shop.","He calls Saud’s mother."],"k":"B","sk":"Locates details about events","b":"161–170","g":"LT"},{"n":23,"t":"mc","s":"Where was the lunch box?","o":["on the bus","in Bader’s school bag","in the classroom cupboard at school","on the kitchen table at home"],"k":"D","sk":"Locates details about plot","b":"171–180","g":"LT"},{"n":24,"t":"mc","s":"Why does Saud bring two oranges the next day?","o":["to sell one","because his mother forgot","to thank Bader for sharing","because he is very hungry"],"k":"C","sk":"Explains character motivation","b":"181–190","g":"LT"},{"n":25,"t":"mc","s":"Which word BEST describes Bader?","o":["lazy","generous","scared","selfish"],"k":"B","sk":"Describes character traits","b":"181–190","g":"LT"}]},{"passage":{"title":"Firefighters","genre":"informational","paras":["Firefighters are brave helpers. They put out fires and keep people safe.","Firefighters wear special coats and helmets. The coats protect them from heat, and the helmets protect their heads.","A fire truck carries long hoses and tall ladders. The ladders help firefighters reach high windows. Firefighters also visit schools to teach children what to do if there is a fire."]},"items":[{"n":26,"t":"mc","s":"What do the ladders help firefighters do?","o":["reach high windows","carry water to the fire","find the school","drive fast"],"k":"A","sk":"Locates details in informational text","b":"161–170","g":"IT"},{"n":27,"t":"mc","s":"What is this text mostly about?","o":["how to drive a fire truck","how fires start","how to build a new fire station","how firefighters keep people safe"],"k":"D","sk":"Determines main idea in informational text","b":"171–180","g":"IT"},{"n":28,"t":"mc","s":"Why do firefighters wear special coats?","o":["to carry hoses","to stay dry in the rain","to protect them from heat","to look nice"],"k":"C","sk":"Understands explicit relationships between ideas","b":"171–180","g":"IT"},{"n":29,"t":"mc","s":"The text says firefighters are **brave**. What does **brave** mean?","o":["quiet and afraid of fires","very tall, very strong and very fast","not afraid to do hard things","very tired"],"k":"C","sk":"Uses context to determine word meaning","b":"171–180","g":"IT"},{"n":30,"t":"mc","s":"Why do firefighters visit schools?","o":["to fix the ladders on the truck","to put out fires at the school and on the bus","to eat lunch","to teach children what to do in a fire"],"k":"D","sk":"Determines specific purpose; locates details","b":"181–190","g":"IT"}]},{"passage":null,"items":[{"n":31,"t":"mc","s":"Read the sentence. “Please **reread** the question before you answer.” What does **reread** mean?","o":["not read","read again","read fast","read loudly"],"k":"B","sk":"Understands how the prefix re- changes meaning","b":"151–160","g":"VO"},{"n":32,"t":"mc","s":"Which word means “not kind”?","o":["unkind","rekind","kindful","kindless"],"k":"A","sk":"Understands how the prefix un- changes meaning","b":"151–160","g":"VO"},{"n":33,"t":"mc","s":"Read the sentence. “The puppy was **tiny**. It could sit in my hand.” What does **tiny** mean?","o":["very old","very small","very angry","very loud"],"k":"B","sk":"Uses context to determine word meaning","b":"161–170","g":"VO"},{"n":34,"t":"mc","s":"Which word means the OPPOSITE of **full**?","o":["big","heavy","empty","round"],"k":"C","sk":"Identifies antonyms","b":"161–170","g":"VO"},{"n":35,"t":"mc","s":"Which word belongs in the group: apple, banana, orange, ___?","o":["chair","blue","run","grape"],"k":"D","sk":"Sorts words into a named category","b":"161–170","g":"VO"},{"n":36,"t":"mc","s":"Which word means “to build again”?","o":["rebuild","buildful","unbuild","builder"],"k":"A","sk":"Understands how the prefix re- changes meaning","b":"161–170","g":"VO"},{"n":37,"t":"mc","s":"Which word means the OPPOSITE of **early**?","o":["first","late","soon","fast"],"k":"B","sk":"Identifies antonyms","b":"161–170","g":"VO"},{"n":38,"t":"mc","s":"Which word is a compound word?","o":["flowing","flowers","sunflower","sunny"],"k":"C","sk":"Understands compound words","b":"171–180","g":"VO"},{"n":39,"t":"mc","s":"A **useful** tool is a tool that —","o":["is full of use; it helps you","is not used","has no use; it does not help","is used again and again"],"k":"A","sk":"Understands how the suffix -ful changes meaning","b":"171–180","g":"VO"},{"n":40,"t":"mc","s":"Read the sentence. “I **bat** the ball with my **bat**.” In this sentence, what is the SECOND **bat**?","o":["an animal that flies at night","a kind of ball","a place to play","a stick used to hit a ball"],"k":"D","sk":"Determines which meaning of a multiple-meaning word fits","b":"171–180","g":"VO"},{"n":41,"t":"mc","s":"Read the sentence. “The room was **silent**; nobody made a sound.” What does **silent** mean?","o":["very quiet","very dark","very hot","very big"],"k":"A","sk":"Uses context to determine word meaning","b":"171–180","g":"VO"},{"n":42,"t":"mc","s":"A **thankful** boy is a boy who is —","o":["without thanks","full of thanks","thanked again","not polite"],"k":"B","sk":"Understands how the suffix -ful changes meaning","b":"171–180","g":"VO"},{"n":43,"t":"mc","s":"Which word is a compound word?","o":["cleaner","brushing","teeth","toothbrush"],"k":"D","sk":"Understands compound words","b":"171–180","g":"VO"}]}]},{"id":"B","note":"Full practice test · 43 questions","sections":[{"passage":{"title":"The Rainy Day Game","genre":"story","paras":["On Friday, the boys wanted to play football, but it was raining hard. “Now we cannot play,” said Sultan sadly.","His big brother Nasser had an idea. He put four cups on the floor. “Let us play cup football,” he said. They rolled a small ball and tried to knock the cups down.","Soon all the boys were laughing. At the end, Sultan said, “This was more fun than football in the rain!”"]},"items":[{"n":1,"t":"mc","s":"Why can the boys NOT play football outside?","o":["It is raining hard.","The ball is lost.","They are sick.","It is too dark."],"k":"A","sk":"Identifies conflict in literary text","b":"161–170","g":"LT"},{"n":2,"t":"mc","s":"Who has the idea for a new game?","o":["Sultan","a friend","their father","Nasser"],"k":"D","sk":"Locates details about characters","b":"161–170","g":"LT"},{"n":3,"t":"mc","s":"How does Sultan feel at the beginning?","o":["proud","sad","happy","scared"],"k":"B","sk":"Infers character feelings","b":"161–170","g":"LT"},{"n":4,"t":"mc","s":"What did Nasser put on the floor?","o":["some books","a football goal","four cups","a big box"],"k":"C","sk":"Locates details about events","b":"161–170","g":"LT"},{"n":5,"t":"mc","s":"How does Sultan feel at the end?","o":["bored","sad","happy","angry"],"k":"C","sk":"Understands how characters change","b":"171–180","g":"LT"}]},{"passage":{"title":"My Cat","genre":"poem","paras":["My cat is soft and white as snow,","She sleeps where sunny windows glow.","At night she plays, she jumps, she runs,","She chases shadows, just for fun."],"poem":true},"items":[{"n":6,"t":"mc","s":"“My cat is soft and white as snow.” What color is the cat?","o":["gray","white","black","brown"],"k":"B","sk":"Interprets simile in context","b":"161–170","g":"LT"},{"n":7,"t":"mc","s":"What does the cat chase?","o":["shadows","birds","balls","mice"],"k":"A","sk":"Locates details in poetry","b":"161–170","g":"LT"},{"n":8,"t":"mc","s":"Where does the cat sleep?","o":["on the roof in the rain","under the bed in the dark","in the garden","where sunny windows glow"],"k":"D","sk":"Locates details in poetry","b":"171–180","g":"LT"},{"n":9,"t":"mc","s":"What does the cat do at night?","o":["sits still","sleeps all night","eats fish","plays and runs"],"k":"D","sk":"Locates details in poetry","b":"171–180","g":"LT"},{"n":10,"t":"mc","s":"Which words rhyme in the poem?","o":["snow and glow","sleeps and white","night and runs","cat and soft"],"k":"A","sk":"Understands characteristics of poetry","b":"171–180","g":"LT"}]},{"passage":{"title":"The Moon","genre":"informational","paras":["The Moon is the closest neighbor of the Earth in space. It goes around the Earth.","The Moon does not make its own light. It shines because light from the Sun hits it.","There is no air or water on the Moon, so plants and animals cannot live there. In 1969, people walked on the Moon for the first time."]},"items":[{"n":11,"t":"mc","s":"When did people first walk on the Moon?","o":["in 2019","in 1969","in 1996","in 1869"],"k":"B","sk":"Locates details in informational text","b":"161–170","g":"IT"},{"n":12,"t":"mc","s":"What does the Moon go around?","o":["the stars","nothing","the Earth","the Sun only"],"k":"C","sk":"Locates details in informational text","b":"161–170","g":"IT"},{"n":13,"t":"mc","s":"What is this text mostly about?","o":["animals that live on the Moon","how to build a rocket","how the Sun makes light","facts about the Moon"],"k":"D","sk":"Determines main idea in informational text","b":"171–180","g":"IT"},{"n":14,"t":"mc","s":"Why does the Moon shine?","o":["It has lamps on it.","Light from the Sun hits it.","It makes its own light at night.","It is very hot."],"k":"B","sk":"Understands explicit relationships between ideas","b":"171–180","g":"IT"},{"n":15,"t":"mc","s":"Why can plants not live on the Moon?","o":["There is no air or water.","People walked on it.","It is too far from the Earth.","It is too small."],"k":"A","sk":"Determines the cause of a situation","b":"181–190","g":"IT"}]},{"passage":{"title":"School Lunch Menu","genre":"menu","paras":["**This Week’s Lunch**","Sunday: rice and chicken","Monday: pasta and salad","Tuesday: fish and rice","Wednesday: chicken sandwich","Thursday: pizza and fruit","*Every day: water, milk or juice*"]},"items":[{"n":16,"t":"mc","s":"On which day is there fish?","o":["Thursday","Sunday","Tuesday","Monday"],"k":"C","sk":"Locates information in a text feature","b":"161–170","g":"IT"},{"n":17,"t":"mc","s":"What is for lunch on Thursday?","o":["pasta and salad","chicken sandwich","rice and chicken","pizza and fruit"],"k":"D","sk":"Locates information in a text feature","b":"161–170","g":"IT"},{"n":18,"t":"mc","s":"What is the purpose of the menu?","o":["to teach students how to cook rice and fish","to tell a story about school food","to tell students what lunch is each day","to sell pizza"],"k":"C","sk":"Determines specific purpose of a graphic","b":"171–180","g":"IT"},{"n":19,"t":"mc","s":"What can students drink every day?","o":["tea, coffee or soda","water, milk or juice","only water every day","only juice"],"k":"B","sk":"Locates information in a text feature","b":"171–180","g":"IT"},{"n":20,"t":"mc","s":"On which TWO days is there rice?","o":["Sunday and Tuesday","Tuesday and Wednesday","Sunday and Monday","Monday and Thursday"],"k":"A","sk":"Interprets information in charts","b":"181–190","g":"IT"}]},{"passage":{"title":"Elephants","genre":"informational","paras":["Elephants are the biggest animals that live on land. An elephant can weigh as much as five cars.","An elephant uses its long trunk like a hand. It can pick up food, drink water and say hello to other elephants.","Elephants live in family groups. The oldest female leads the group and remembers where to find water."]},"items":[{"n":21,"t":"mc","s":"Who leads an elephant family group?","o":["the oldest female","the youngest baby","the biggest male","a different animal"],"k":"A","sk":"Locates details in informational text","b":"161–170","g":"IT"},{"n":22,"t":"mc","s":"What is this text mostly about?","o":["how people find water in the hot desert","animals that live in the deep sea","what elephants are like and how they live","how to wash a car"],"k":"C","sk":"Determines main idea in informational text","b":"171–180","g":"IT"},{"n":23,"t":"ms","s":"Which TWO things can an elephant do with its trunk? Choose TWO answers.","o":["climb trees","swim under the sea","pick up food","drink water","fly"],"k":"C, D","sk":"Locates key details","b":"171–180","g":"IT"},{"n":24,"t":"mc","s":"The author compares an elephant to five cars to show that it is —","o":["very old","very heavy","very loud","very fast"],"k":"B","sk":"Understands explicit relationships between ideas","b":"181–190","g":"IT"},{"n":25,"t":"mc","s":"Why is the leader important?","o":["She is the fastest.","She has the longest trunk in the herd.","She sleeps the most.","She remembers where to find water."],"k":"D","sk":"Determines the cause of a situation","b":"181–190","g":"IT"}]},{"passage":{"title":"The Kind Shopkeeper","genre":"story","paras":["Amer went to the small shop to buy bread. When he got home, he counted his change. The shopkeeper had given him five riyals too much.","“The money is not mine,” Amer thought. He walked back to the shop and gave the money to the shopkeeper.","The shopkeeper was surprised and happy. “Thank you, young man,” he said. “Honest people are rare.” He gave Amer a small bag of sweets."]},"items":[{"n":26,"t":"mc","s":"What did Amer buy?","o":["fruit","sweets","milk","bread"],"k":"D","sk":"Locates details about events","b":"161–170","g":"LT"},{"n":27,"t":"mc","s":"What did Amer notice when he got home?","o":["He forgot to buy the bread for lunch.","He had five riyals too much.","The bread was old.","He lost his money."],"k":"B","sk":"Identifies conflict in literary text","b":"171–180","g":"LT"},{"n":28,"t":"mc","s":"Why does Amer go back to the shop?","o":["He wants to return money that is not his.","He wants to buy milk.","He wants to buy more sweets with the money.","He forgot his school bag there."],"k":"A","sk":"Explains character motivation","b":"181–190","g":"LT"},{"n":29,"t":"mc","s":"Which word BEST describes Amer?","o":["greedy","lazy","honest","rude"],"k":"C","sk":"Describes character traits","b":"181–190","g":"LT"},{"n":30,"t":"mc","s":"What does the shopkeeper mean by “Honest people are rare”?","o":["Not many people are honest like Amer.","He does not like people who are honest.","Honest people buy bread.","Honest people are very old."],"k":"A","sk":"Determines the meaning of a phrase in context","b":"191–200","g":"LT"}]},{"passage":null,"items":[{"n":31,"t":"mc","s":"Which word means “not able”?","o":["ableful","ableless","unable","reable"],"k":"C","sk":"Understands how the prefix un- changes meaning","b":"151–160","g":"VO"},{"n":32,"t":"mc","s":"Read the sentence. “Please **repaint** the old door.” What does **repaint** mean?","o":["not paint","paint badly","clean","paint again"],"k":"D","sk":"Understands how the prefix re- changes meaning","b":"151–160","g":"VO"},{"n":33,"t":"mc","s":"Read the sentence. “The cake was **delicious**, so I ate two pieces.” What does **delicious** mean?","o":["very small","very tasty","very hard","very old"],"k":"B","sk":"Uses context to determine word meaning","b":"161–170","g":"VO"},{"n":34,"t":"mc","s":"Which word means the OPPOSITE of **open**?","o":["big","closed","new","wide"],"k":"B","sk":"Identifies antonyms","b":"161–170","g":"VO"},{"n":35,"t":"mc","s":"Which word belongs in the group: red, blue, green, ___?","o":["yellow","jump","table","happy"],"k":"A","sk":"Sorts words into a named category","b":"161–170","g":"VO"},{"n":36,"t":"mc","s":"Which word means “to use again”?","o":["useless","unuse","reuse","useful"],"k":"C","sk":"Understands how the prefix re- changes meaning","b":"161–170","g":"VO"},{"n":37,"t":"mc","s":"Which word means the OPPOSITE of **wet**?","o":["soft","cold","clean","dry"],"k":"D","sk":"Identifies antonyms","b":"161–170","g":"VO"},{"n":38,"t":"mc","s":"Which word is a compound word?","o":["bedroom","reading","bedding","sleepy"],"k":"A","sk":"Understands compound words","b":"171–180","g":"VO"},{"n":39,"t":"mc","s":"A **painless** test is a test that is —","o":["very long","without pain","full of pain","painted"],"k":"B","sk":"Understands how the suffix -less changes meaning","b":"171–180","g":"VO"},{"n":40,"t":"mc","s":"Read the sentence. “Please **fold** your paper in half.” What does **fold** mean?","o":["cut into many small pieces","color","bend one part over another","throw it away in the bin"],"k":"C","sk":"Uses context to determine word meaning","b":"171–180","g":"VO"},{"n":41,"t":"mc","s":"Read the sentence. “The road was **busy**; there were many cars.” What does **busy** mean here?","o":["dirty","closed for the night","empty, with no cars at all","full of activity"],"k":"D","sk":"Uses context to determine word meaning","b":"171–180","g":"VO"},{"n":42,"t":"mc","s":"A **homeless** cat is a cat that is —","o":["at home again","without a home","full of homes","very happy"],"k":"B","sk":"Understands how the suffix -less changes meaning","b":"171–180","g":"VO"},{"n":43,"t":"mc","s":"“The test was **a piece of cake**.” What does this mean?","o":["The test was very easy.","The test was about food.","The test was very long.","The test was hard."],"k":"A","sk":"Understands the meaning of common idioms","b":"181–190","g":"VO"}]}]},{"id":"C","note":"Full practice test · 43 questions · harder","sections":[{"passage":{"title":"Brush Your Teeth","genre":"informational","paras":["**Why Brush?**","Food and sugar stay on your teeth after you eat. If you do not brush, they can make holes in your teeth.","**How to Brush**","Brush two times every day, in the morning and before bed. Brush for two minutes. Brush the front, the back and the top of every tooth.","**See a Dentist**","A dentist is a doctor for teeth. Visit a dentist two times a year."]},"items":[{"n":1,"t":"mc","s":"How long should you brush?","o":["two minutes","ten seconds","five minutes","two hours"],"k":"A","sk":"Locates details in informational text","b":"161–170","g":"IT"},{"n":2,"t":"mc","s":"What is a **dentist**?","o":["a kind of toothbrush","a teacher","a kind of sugar","a doctor for teeth"],"k":"D","sk":"Determines domain-specific word meaning in context","b":"161–170","g":"IT"},{"n":3,"t":"mc","s":"Why should you brush your teeth?","o":["so you can sleep well","so you can eat more sugar every day","so food and sugar do not make holes in them","so your teeth grow faster and much stronger"],"k":"C","sk":"Determines the cause of a situation","b":"171–180","g":"IT"},{"n":4,"t":"mc","s":"Under which heading can you learn about a dentist?","o":["Brush Your Teeth","See a Dentist","Why Brush?","How to Brush"],"k":"B","sk":"Understands the purpose of headings","b":"171–180","g":"IT"},{"n":5,"t":"mc","s":"What is the author’s purpose?","o":["to tell a funny story about a dentist","to make you buy a new toothbrush","to teach how to keep teeth healthy","to describe a hospital"],"k":"C","sk":"Determines specific purpose of an informational text","b":"181–190","g":"IT"}]},{"passage":{"title":"The Best Gift","genre":"story","paras":["Fahad wanted to give his mother a gift for Eid. He had only five riyals. “That is not enough for a nice gift,” he thought.","His sister Noura had an idea. “Make something with your hands,” she said. Fahad found colored paper and glue. He worked all afternoon. He made a card with a big yellow sun and wrote, “You light up our home.”","On Eid morning, Fahad gave the card to his mother. Her eyes filled with happy tears. “This is the best gift,” she said, “because you made it with love.” She put the card on the wall where everyone could see it."]},"items":[{"n":6,"t":"mc","s":"How much money did Fahad have?","o":["ten riyals","fifty riyals","one riyal","five riyals"],"k":"D","sk":"Locates details in literary text","b":"161–170","g":"LT"},{"n":7,"t":"mc","s":"What is Fahad’s problem at the beginning?","o":["He forgets that Eid is coming soon.","He does not have enough money for a gift.","He loses his colored paper and his glue.","His sister is angry with him."],"k":"B","sk":"Identifies conflict in literary text","b":"171–180","g":"LT"},{"n":8,"t":"mc","s":"How does Noura help Fahad?","o":["She tells him to make a gift with his hands.","She gives him money so he can buy a gift.","She makes the card for him herself.","She buys the gift for him."],"k":"A","sk":"Analyzes how characters’ actions contribute to plot","b":"171–180","g":"LT"},{"n":9,"t":"tp","s":"Part A: Why does Mother say the card is “the best gift”?","o":["because it cost a lot of money","because it is very big","because Fahad made it with love","because Noura made it"],"k":"C","sk":"Determines details that support an inference","b":"181–190","g":"LT","pb":{"s":"What does Mother do that supports the answer to Part A?","o":["She gives Fahad five riyals.","She goes to the market.","She puts the card on the wall where everyone can see it.","She buys more paper."],"k":"C"}},{"n":10,"t":"mc","s":"What is the lesson of this story?","o":["A gift made with love can be worth more than money.","You should always save your money for gifts at Eid.","Paper and glue are too expensive to buy.","Sisters should make all the gifts."],"k":"A","sk":"Determines theme in literary text","b":"181–190","g":"LT"}]},{"passage":{"title":"The Two Goats","genre":"fable","paras":["Two goats met in the middle of a narrow bridge. Below them was a fast river. “Move back!” said the first goat. “No, YOU move back!” said the second goat.","They pushed with their heads, and both goats almost fell into the water.","Then the first goat had a better idea. He lay down flat. The second goat stepped carefully over him. Both goats crossed the bridge safely."]},"items":[{"n":11,"t":"mc","s":"Where do the goats meet?","o":["in a field","on the top of a high mountain","next to the farmer’s house on the hill","in the middle of a narrow bridge"],"k":"D","sk":"Identifies setting","b":"161–170","g":"LT"},{"n":12,"t":"mc","s":"What happens when the goats push each other?","o":["They fall asleep.","They almost fall into the water.","They become good friends at once.","The old bridge breaks in two."],"k":"B","sk":"Locates details about events","b":"171–180","g":"LT"},{"n":13,"t":"mc","s":"How does the first goat solve the problem?","o":["He runs back home.","He jumps into the river and swims to the other side.","He lies down so the other goat can step over him.","He calls the farmer to come and help."],"k":"C","sk":"Identifies resolution","b":"171–180","g":"LT"},{"n":14,"t":"mc","s":"How do the goats feel when they say “Move back!”?","o":["stubborn","shy","happy","sleepy"],"k":"A","sk":"Infers character feelings","b":"181–190","g":"LT"},{"n":15,"t":"mc","s":"What is the lesson of the fable?","o":["Goats should never cross rivers alone.","Working things out is better than fighting.","Bridges are dangerous places for all goats.","Goats can swim."],"k":"B","sk":"Determines the moral of a fable","b":"181–190","g":"LT"}]},{"passage":{"title":"Rain in the Desert","genre":"poem","paras":["The sky was gray, the air was still,","Then drip and drop came down the hill.","Tap, tap, tap upon the sand,","The rain came dancing on the land.","","The thirsty flowers raised their heads,","The beetles ran from sandy beds,","And when the sun came out to stay,","The desert smiled a brand-new day."],"poem":true},"items":[{"n":16,"t":"mc","s":"What color was the sky at the beginning of the poem?","o":["black","blue","orange","gray"],"k":"D","sk":"Locates details in poetry","b":"161–170","g":"LT"},{"n":17,"t":"mc","s":"The poem says, “Tap, tap, tap upon the sand.” Why does the poet use these words?","o":["to show the sound of the rain","to show how hot the sun is today","to name a kind of flower","to tell how beetles walk"],"k":"A","sk":"Interprets onomatopoeia in context","b":"171–180","g":"LT"},{"n":18,"t":"mc","s":"“The rain came dancing on the land.” What does this line mean?","o":["The rain made the land hot and dry.","The rain was a real dancer on the land.","The rain fell in a happy, lively way.","The rain stopped quickly."],"k":"C","sk":"Interprets personification in context","b":"171–180","g":"LT"},{"n":19,"t":"mc","s":"Why are the flowers called “thirsty”?","o":["They wanted food.","They needed water.","They were sleeping.","They were very tall."],"k":"B","sk":"Determines the meaning of a figurative word","b":"181–190","g":"LT"},{"n":20,"t":"mc","s":"How does the desert change from the beginning to the end of the poem?","o":["It is wet and green at first, and dry at the end.","It is happy and bright at first, and sad and gray at the end.","It is dark at first, and darker at the end.","It is still and gray at first, and happy and bright at the end."],"k":"D","sk":"Analyzes how specific parts of a poem contribute to its meaning","b":"191–200","g":"LT"}]},{"passage":{"title":"Busy Honeybees","genre":"informational","paras":["**Bees Work Together**","Honeybees live together in a home called a hive. Thousands of bees live in one hive, and every bee has a job.","**Making Honey**","Worker bees fly from flower to flower. They drink a sweet juice called nectar. Back at the hive, the bees turn the nectar into honey. Honey is food for the bees in winter.","**Helping Plants**","When a bee visits a flower, yellow powder called pollen sticks to its body. The bee carries the pollen to the next flower. This helps plants make seeds and fruit."]},"items":[{"n":21,"t":"mc","s":"Where do honeybees live?","o":["in a burrow","in a nest of sticks","in the sand","in a hive"],"k":"D","sk":"Locates details in informational text","b":"161–170","g":"IT"},{"n":22,"t":"mc","s":"What is **nectar**?","o":["a bee’s home","a sweet juice in flowers","a kind of seed","a yellow powder on the bee’s legs"],"k":"B","sk":"Determines domain-specific word meaning in context","b":"171–180","g":"IT"},{"n":23,"t":"mc","s":"What is the main idea of this text?","o":["Honeybees work together and help plants.","Bees are dangerous insects that sting people.","Honey is good food for people to eat.","Flowers grow in winter."],"k":"A","sk":"Determines main idea in informational text","b":"181–190","g":"IT"},{"n":24,"t":"mc","s":"What happens because a bee carries pollen from flower to flower?","o":["The bee makes wax.","The hive gets bigger and bigger.","Plants can make seeds and fruit.","The flowers lose their color."],"k":"C","sk":"Determines the effect of an event","b":"181–190","g":"IT"},{"n":25,"t":"mc","s":"Under which heading would you read about how honey is made?","o":["Busy Honeybees","Bees Work Together","Helping Plants","Making Honey"],"k":"D","sk":"Understands the purpose of headings","b":"181–190","g":"IT"}]},{"passage":{"title":"Visit the City Zoo","genre":"map","paras":["**City Zoo — Where to Find the Animals**","Gate → turn left → Lions and Tigers","Gate → walk straight → Elephants → Giraffes","Gate → turn right → Birds → Snakes","Café: next to the Giraffes · Open 9:00 to 5:00 every day · Tickets: children 10 riyals, adults 20 riyals"]},"items":[{"n":26,"t":"mc","s":"Which animals are near the café?","o":["the lions","the giraffes","the birds","the snakes"],"k":"B","sk":"Locates information in maps","b":"171–180","g":"IT"},{"n":27,"t":"mc","s":"At what time does the zoo close?","o":["12:00","9:00","5:00","10:00"],"k":"C","sk":"Locates information in a text feature","b":"171–180","g":"IT"},{"n":28,"t":"mc","s":"A visitor turns right at the gate. What will he see FIRST?","o":["the birds","the lions","the elephants","the snakes"],"k":"A","sk":"Understands sequence; reads directions","b":"181–190","g":"IT"},{"n":29,"t":"mc","s":"Why is this information useful to visitors?","o":["It explains what giraffes eat.","It helps them find the animals.","It tells a story about a lion.","It shows how to feed birds."],"k":"B","sk":"Determines specific purpose of a graphic","b":"181–190","g":"IT"},{"n":30,"t":"mc","s":"A father and one child buy tickets. How much do they pay?","o":["10 riyals","40 riyals","30 riyals","20 riyals"],"k":"C","sk":"Integrates information from a text feature","b":"191–200","g":"IT"}]},{"passage":null,"items":[{"n":31,"t":"mc","s":"Which word means “not fair”?","o":["unfair","fairness","fairful","refair"],"k":"A","sk":"Understands how the prefix un- changes meaning","b":"161–170","g":"VO"},{"n":32,"t":"mc","s":"Which word means almost the same as **little**?","o":["big","tall","long","small"],"k":"D","sk":"Uses synonym relationships","b":"161–170","g":"VO"},{"n":33,"t":"mc","s":"Which word belongs in the group: car, bus, train, ___?","o":["sunny","airplane","chair","apple"],"k":"B","sk":"Sorts words into a named category","b":"161–170","g":"VO"},{"n":34,"t":"mc","s":"The children were **careless** and dropped the glass. What does **careless** mean?","o":["without care","cared again","very careful","full of care"],"k":"A","sk":"Understands how the suffix -less changes meaning","b":"171–180","g":"VO"},{"n":35,"t":"mc","s":"Which word means almost the same as **begin**?","o":["close","finish","stop","start"],"k":"D","sk":"Uses synonym relationships","b":"171–180","g":"VO"},{"n":36,"t":"mc","s":"Read the sentence. “Please **disconnect** the computer before you clean it.” What does **disconnect** mean?","o":["to clean it","to connect it again to the wall","to stop it being connected","to connect it well"],"k":"C","sk":"Understands how the prefix dis- changes meaning","b":"171–180","g":"VO"},{"n":37,"t":"mc","s":"“It is raining **cats and dogs**.” What does this mean?","o":["Cats and dogs are playing.","It is not raining.","It is raining very hard.","Animals are falling from the sky."],"k":"C","sk":"Understands the meaning of common idioms","b":"171–180","g":"VO"},{"n":38,"t":"mc","s":"Which word tells how someone feels?","o":["under","quickly","table","nervous"],"k":"D","sk":"Demonstrates understanding of words that convey emotion","b":"171–180","g":"VO"},{"n":39,"t":"mc","s":"Read the sentence. “The lion **roared** so loudly that we covered our ears.” What does **roared** mean?","o":["made a very loud sound","ran very fast across the field","slept","ate quickly"],"k":"A","sk":"Uses context to determine word meaning","b":"171–180","g":"VO"},{"n":40,"t":"mc","s":"Read the sentence. “After the long race, Saad was **exhausted** and sat down to rest.” What does **exhausted** mean?","o":["very happy","very tired","very fast","very hungry"],"k":"B","sk":"Uses context to determine word meaning","b":"181–190","g":"VO"},{"n":41,"t":"mc","s":"Read the sentence. “The **light** box was easy to carry.” What does **light** mean here?","o":["bright","not dark","not heavy","a lamp"],"k":"C","sk":"Determines which meaning of a multiple-meaning word fits","b":"181–190","g":"VO"},{"n":42,"t":"mc","s":"The word **telescope** has the root **tele**, which means “far.” A telescope helps you —","o":["hear music","count the stars quickly at night","write letters","see things that are far away"],"k":"D","sk":"Applies knowledge of Greek or Latin roots","b":"181–190","g":"VO"},{"n":43,"t":"mc","s":"Read the sentence. “Please **check** your answers before you finish.” What does **check** mean?","o":["hide","look again to make sure they are right","copy them onto a new page","erase them all and start the test again"],"k":"B","sk":"Determines which meaning of a multiple-meaning word fits","b":"181–190","g":"VO"}]}]},{"id":"D","note":"Full practice test · 43 questions · harder","sections":[{"passage":{"title":"Yusuf’s First Fish","genre":"story","paras":["Yusuf went fishing with his uncle on a small boat. For two hours, nothing happened. Yusuf wanted to go home.","“Fishing teaches patience,” said his uncle. “Wait a little longer.”","Just then, the line pulled hard. Yusuf held the rod with both hands and slowly pulled in a big silver fish. His uncle cheered. “You see? Good things come to those who wait!”"]},"items":[{"n":1,"t":"mc","s":"Where are Yusuf and his uncle?","o":["at the market","at school","in a garden","on a small boat"],"k":"D","sk":"Identifies setting","b":"161–170","g":"LT"},{"n":2,"t":"mc","s":"What does the uncle tell Yusuf to do?","o":["jump into the water","wait a little longer","go home","buy a fish"],"k":"B","sk":"Locates details about events","b":"161–170","g":"LT"},{"n":3,"t":"mc","s":"Why does Yusuf want to go home?","o":["Nothing happens for two hours.","The boat is broken and leaking.","He is cold and wet from the sea.","He caught many fish."],"k":"A","sk":"Explains character motivation","b":"171–180","g":"LT"},{"n":4,"t":"mc","s":"What happens after the line pulls hard?","o":["The boat goes home.","Yusuf falls into the sea.","Yusuf pulls in a big fish.","The rod breaks."],"k":"C","sk":"Understands sequence in literary text","b":"171–180","g":"LT"},{"n":5,"t":"mc","s":"What is the lesson of the story?","o":["Fishing is boring for young children.","Uncles are always right.","Boats are dangerous on windy days.","Being patient can bring good results."],"k":"D","sk":"Determines theme in literary text","b":"181–190","g":"LT"}]},{"passage":{"title":"The Sand Castle","genre":"story","paras":["Faris and his little brother built a big sand castle at the beach. It had four towers and a wall made of shells.","Suddenly, a big wave rushed up the sand and washed away one tower. His little brother began to cry. Faris wanted to cry too, but he took a deep breath.","“Let us build it again,” he said, “but farther from the water.” This time, they built the castle near the dry sand. The waves could not reach it, and the castle stood until sunset."]},"items":[{"n":6,"t":"mc","s":"What was the castle wall made of?","o":["wood","paper","shells","rocks"],"k":"C","sk":"Locates details in literary text","b":"161–170","g":"LT"},{"n":7,"t":"mc","s":"What problem do the brothers have?","o":["Their bucket breaks into many small pieces.","A wave washes away part of their castle.","They lose their shells in the sand.","It starts to rain."],"k":"B","sk":"Identifies conflict in literary text","b":"171–180","g":"LT"},{"n":8,"t":"mc","s":"How do the brothers solve the problem?","o":["They build the castle farther from the water.","They build a tall wall of rocks around it.","They go home and build it in the yard.","They stop playing."],"k":"A","sk":"Identifies resolution","b":"171–180","g":"LT"},{"n":9,"t":"mc","s":"“Faris wanted to cry too, but he took a deep breath.” What does this show about Faris?","o":["He tries to stay calm.","He is angry with his brother.","He is very tired.","He does not care."],"k":"A","sk":"Determines details that reveal character feelings","b":"181–190","g":"LT"},{"n":10,"t":"mc","s":"What lesson can you learn from this story?","o":["Little brothers always cry when they lose.","When something goes wrong, try again in a smarter way.","Never go to the beach when it is windy or cloudy.","Shells are better than sand."],"k":"B","sk":"Determines theme in literary text","b":"181–190","g":"LT"}]},{"passage":{"title":"The Proud Rooster","genre":"fable","paras":["A rooster crowed every morning. “The sun comes up because I call it,” he told the other animals.","One morning, the rooster overslept. He did not crow at all. But when he woke up, the sun was already high in the sky.","“Oh,” said the rooster quietly. “The sun did not need me after all.” From then on, he crowed happily, but he never bragged again."]},"items":[{"n":11,"t":"mc","s":"When did the rooster usually crow?","o":["only on Fridays","every night","every morning","at lunchtime"],"k":"C","sk":"Locates details about characters","b":"161–170","g":"LT"},{"n":12,"t":"mc","s":"What does the rooster believe at the beginning?","o":["He is the fastest animal.","The sun is his best friend in the sky.","The other animals are lazy.","The sun rises because he crows."],"k":"D","sk":"Locates details about characters","b":"171–180","g":"LT"},{"n":13,"t":"mc","s":"What happens when the rooster oversleeps?","o":["The sun comes up anyway.","It rains all day.","The sun does not come up.","The animals wake him."],"k":"A","sk":"Locates details about events","b":"171–180","g":"LT"},{"n":14,"t":"mc","s":"Which word BEST describes the rooster at the beginning?","o":["sleepy","shy","proud","kind"],"k":"C","sk":"Describes character traits","b":"181–190","g":"LT"},{"n":15,"t":"mc","s":"What is the lesson of the fable?","o":["Always wake up early in the morning.","Do not brag about things you do not do.","Roosters are noisy.","Roosters are noisy and should be quiet."],"k":"B","sk":"Determines the moral of a fable","b":"181–190","g":"LT"}]},{"passage":{"title":"Penguins","genre":"informational","paras":["**Birds That Cannot Fly**","Penguins are birds, but they cannot fly. Their wings are like flippers. They use them to swim fast in the sea.","**Keeping Warm**","Many penguins live in very cold places. They have thick feathers and a layer of fat under their skin. In storms, penguins stand close together to stay warm."]},"items":[{"n":16,"t":"mc","s":"What do penguins use their wings for?","o":["flying","eating","digging","swimming"],"k":"D","sk":"Locates details in informational text","b":"161–170","g":"IT"},{"n":17,"t":"mc","s":"Under which heading can you read about how penguins stay warm?","o":["Birds That Cannot Fly","Keeping Warm","Swimming Fast","Penguins"],"k":"B","sk":"Understands the purpose of headings","b":"171–180","g":"IT"},{"n":18,"t":"mc","s":"What is under a penguin’s skin?","o":["feathers","water","a layer of ice","a layer of fat"],"k":"D","sk":"Locates details in informational text","b":"171–180","g":"IT"},{"n":19,"t":"mc","s":"Why do penguins stand close together in storms?","o":["to stay warm","to find food","to swim faster","to play a game"],"k":"A","sk":"Determines the cause of a situation","b":"181–190","g":"IT"},{"n":20,"t":"mc","s":"The author says penguin wings are “like flippers.” This means the wings —","o":["can help them fly high over the water","are very colorful","are flat and good for swimming","are very long feathers"],"k":"C","sk":"Understands explicit relationships between ideas","b":"181–190","g":"IT"}]},{"passage":{"title":"Bus Timetable","genre":"timetable","paras":["**School Bus Route 3 — Morning**","Palm Street: 6:30","Market Square: 6:40","Green Park: 6:50","Arrive at school: 7:05"]},"items":[{"n":21,"t":"mc","s":"What time does the bus stop at Market Square?","o":["6:50","6:40","7:05","6:30"],"k":"B","sk":"Locates information in a text feature","b":"161–170","g":"IT"},{"n":22,"t":"mc","s":"What time does the bus leave Palm Street?","o":["6:30","7:05","6:40","6:50"],"k":"A","sk":"Locates information in a text feature","b":"161–170","g":"IT"},{"n":23,"t":"mc","s":"Which stop comes right after Market Square?","o":["Market Square","the school","Green Park","Palm Street"],"k":"C","sk":"Understands sequence in informational text","b":"171–180","g":"IT"},{"n":24,"t":"mc","s":"Who would MOST need this timetable?","o":["shop owners","teachers at lunch","farmers who work in the park","students who ride bus 3"],"k":"D","sk":"Determines specific purpose of a text","b":"181–190","g":"IT"},{"n":25,"t":"mc","s":"A boy gets on at Palm Street. How long is his ride to school?","o":["10 minutes","25 minutes","35 minutes","1 hour"],"k":"C","sk":"Integrates information from a text feature","b":"191–200","g":"IT"}]},{"passage":{"title":"Recycling Paper","genre":"informational","paras":["Paper is made from trees. When we recycle old paper, we help save trees.","First, old paper is collected and taken to a factory. Next, it is mixed with water until it is soft. Then it is pressed flat and dried. Finally, it becomes new paper.","You can help by putting old paper in the blue recycling bin."]},"items":[{"n":26,"t":"mc","s":"What is paper made from?","o":["trees","plastic","rocks","glass"],"k":"A","sk":"Locates details in informational text","b":"161–170","g":"IT"},{"n":27,"t":"mc","s":"What happens FIRST when paper is recycled?","o":["It becomes new paper.","Old paper is collected.","It is pressed flat.","It is dried."],"k":"B","sk":"Understands sequence in informational text","b":"171–180","g":"IT"},{"n":28,"t":"mc","s":"What happens right after paper is mixed with water?","o":["It is cut from trees.","It goes into the blue bin.","It is collected.","It is pressed flat and dried."],"k":"D","sk":"Identifies process as a structure","b":"181–190","g":"IT"},{"n":29,"t":"mc","s":"Why is recycling paper good?","o":["It makes paper wet.","It uses more trees.","It makes factories close.","It helps save trees."],"k":"D","sk":"Determines the effect of an event","b":"181–190","g":"IT"},{"n":30,"t":"mc","s":"Which words tell the order of the steps?","o":["old, soft, flat, new","paper, water, factory, bin","first, next, then, finally","we, you, it, they"],"k":"C","sk":"Understands sequence signal words","b":"181–190","g":"IT"}]},{"passage":null,"items":[{"n":31,"t":"mc","s":"Which word means almost the same as **quick**?","o":["fast","late","slow","heavy"],"k":"A","sk":"Uses synonym relationships","b":"161–170","g":"VO"},{"n":32,"t":"mc","s":"Which word means “to tell again”?","o":["tellful","retell","teller","untell"],"k":"B","sk":"Understands how the prefix re- changes meaning","b":"171–180","g":"VO"},{"n":33,"t":"mc","s":"Which word means almost the same as **happy**?","o":["tired","sad","angry","glad"],"k":"D","sk":"Uses synonym relationships","b":"171–180","g":"VO"},{"n":34,"t":"mc","s":"“My little sister is **as busy as a bee**.” What does this mean?","o":["She can fly very high.","She is sleeping.","She does many things.","She likes honey."],"k":"C","sk":"Interprets simile in context","b":"171–180","g":"VO"},{"n":35,"t":"mc","s":"Which word tells how someone feels?","o":["worried","chair","slowly","behind"],"k":"A","sk":"Demonstrates understanding of emotion words","b":"171–180","g":"VO"},{"n":36,"t":"mc","s":"Which word means “not like”?","o":["relike","dislike","likeful","likeness"],"k":"B","sk":"Understands how the prefix dis- changes meaning","b":"171–180","g":"VO"},{"n":37,"t":"mc","s":"Read the sentence. “The **enormous** truck could carry ten cars.” What does **enormous** mean?","o":["very big","very old","very fast","very loud"],"k":"A","sk":"Uses context to determine word meaning","b":"181–190","g":"VO"},{"n":38,"t":"mc","s":"Read the sentence. “Turn **right** at the shop.” What does **right** mean here?","o":["very good","the opposite of left","a fair rule for everyone","correct"],"k":"B","sk":"Determines which meaning of a multiple-meaning word fits","b":"181–190","g":"VO"},{"n":39,"t":"mc","s":"The word **disappear** means —","o":["to come into view","to look happy","to go out of sight","to appear again"],"k":"C","sk":"Understands how the prefix dis- changes meaning","b":"181–190","g":"VO"},{"n":40,"t":"mc","s":"Read the sentence. “The road was **slippery** after the rain, so we walked carefully.” What does **slippery** mean?","o":["busy and full of cars","very short","dry, dusty and full of holes","smooth and easy to fall on"],"k":"D","sk":"Uses context to determine word meaning","b":"181–190","g":"VO"},{"n":41,"t":"mc","s":"Read the sentence. “The flowers were **fragrant** and smelled lovely.” What does **fragrant** mean?","o":["very old","brightly colored","having a nice smell","very tall"],"k":"C","sk":"Uses context to determine word meaning","b":"181–190","g":"VO"},{"n":42,"t":"mc","s":"Read the sentence. “The **bark** of the tree was rough.” What does **bark** mean here?","o":["the sound that a dog makes","a kind of boat","a leaf","the outside covering of a tree"],"k":"D","sk":"Determines which meaning of a multiple-meaning word fits","b":"181–190","g":"VO"},{"n":43,"t":"mc","s":"The root **port** means “carry.” Which word means “to carry goods to another country”?","o":["airport","export","report","portrait"],"k":"B","sk":"Applies knowledge of Greek or Latin roots","b":"191–200","g":"VO"}]}]},{"id":"E","note":"Final full practice test · 43 questions · hardest","sections":[{"passage":{"title":"The Quiet Helper","genre":"story","paras":["Every morning, Mr. Saeed, the school guard, opened the gate and said, “Good morning, champions!” Most students hurried past him without a word.","One day, Tariq saw that Mr. Saeed looked tired. He was carrying heavy boxes of books to the library. Tariq put down his bag and took two boxes. Two more boys came to help, and soon all the boxes were in the library.","The next morning, Mr. Saeed said, “Good morning, champions!” This time, a whole line of students answered, “Good morning, Mr. Saeed!” He smiled the biggest smile Tariq had ever seen."]},"items":[{"n":1,"t":"mc","s":"What does Mr. Saeed say every morning?","o":["“Good morning, champions!”","“Go to the library now, boys!”","“Hurry up!”","“Thank you, Tariq!”"],"k":"A","sk":"Locates details about characters","b":"161–170","g":"LT"},{"n":2,"t":"mc","s":"What does Tariq notice about Mr. Saeed?","o":["He is angry with the students at the gate.","He is late for work and in a hurry.","He has lost his keys.","He looks tired and is carrying heavy boxes."],"k":"D","sk":"Locates details about characters","b":"171–180","g":"LT"},{"n":3,"t":"mc","s":"What happens after Tariq starts to help?","o":["The heavy boxes fall down.","Two more boys come to help.","Mr. Saeed goes home.","The bell rings."],"k":"B","sk":"Understands sequence in literary text","b":"171–180","g":"LT"},{"n":4,"t":"mc","s":"Why does Mr. Saeed smile “the biggest smile” at the end?","o":["The library is closed.","It is the weekend, and he can rest.","The students now greet him back kindly.","He gets a new job at a bigger school."],"k":"C","sk":"Makes inferences from literary text","b":"181–190","g":"LT"},{"n":5,"t":"mc","s":"What is the theme of the story?","o":["Students should hurry to class.","Small acts of kindness can change how people treat each other.","Guards should open the school gates early every day for students.","Libraries need many new books for students to read."],"k":"B","sk":"Determines theme in literary text","b":"191–200","g":"LT"}]},{"passage":{"title":"Book Fair","genre":"poster","paras":["**Come to the School Book Fair!**","When: Monday to Wednesday, 9:00 to 12:00","Where: the school hall","Story books: 10 riyals · Science books: 15 riyals","*Buy 2 books and get a free bookmark!*"]},"items":[{"n":6,"t":"mc","s":"Where is the book fair?","o":["in the park","in the classroom","in the school hall","in the library"],"k":"C","sk":"Locates information in a text feature","b":"161–170","g":"IT"},{"n":7,"t":"mc","s":"On which days is the book fair?","o":["Sunday to Thursday","only Friday","only Monday","Monday to Wednesday"],"k":"D","sk":"Locates information in a text feature","b":"161–170","g":"IT"},{"n":8,"t":"mc","s":"How can you get a free bookmark?","o":["by buying 2 books","by bringing a friend","by reading a story","by coming on Monday"],"k":"A","sk":"Locates details in informational text","b":"181–190","g":"IT"},{"n":9,"t":"mc","s":"Why did the school make this poster?","o":["to invite students to the book fair","to teach science","to tell a story about books","to show students the map of the school"],"k":"A","sk":"Determines specific purpose of a poster","b":"181–190","g":"IT"},{"n":10,"t":"mc","s":"How much do one story book and one science book cost together?","o":["10 riyals","15 riyals","20 riyals","25 riyals"],"k":"D","sk":"Integrates information from a text feature","b":"191–200","g":"IT"}]},{"passage":{"title":"The Desert Hedgehog","genre":"informational","paras":["**A Prickly Animal**","The desert hedgehog is a small animal covered with sharp spines. When it is afraid, it rolls into a tight ball, and its spines point out.","**Day and Night**","In the hot day, the hedgehog sleeps in a cool hole. At night, it comes out to eat insects, eggs and small lizards.","**Living Without Much Water**","The hedgehog gets most of the water it needs from the food it eats."]},"items":[{"n":11,"t":"mc","s":"When does the hedgehog look for food?","o":["at noon","in the morning","at night","in the rain"],"k":"C","sk":"Locates details in informational text","b":"171–180","g":"IT"},{"n":12,"t":"mc","s":"Why does the hedgehog roll into a ball?","o":["to drink water","to protect itself when it is afraid","to catch insects for dinner","to sleep in the warm sun all afternoon"],"k":"B","sk":"Determines the cause of a situation","b":"181–190","g":"IT"},{"n":13,"t":"mc","s":"How does the hedgehog get most of its water?","o":["from rivers and lakes","from the sea","from the food it eats","from rain"],"k":"C","sk":"Locates details in informational text","b":"181–190","g":"IT"},{"n":14,"t":"mc","s":"Under which heading can you read about what the hedgehog eats?","o":["Day and Night","A Prickly Animal","Living Without Much Water","The Desert Hedgehog"],"k":"A","sk":"Understands the purpose of headings","b":"181–190","g":"IT"},{"n":15,"t":"mc","s":"The text says the hedgehog is **prickly**. What does **prickly** mean?","o":["very fast","very soft, like a pillow","very loud and noisy","covered with sharp points"],"k":"D","sk":"Uses context to determine word meaning","b":"181–190","g":"IT"}]},{"passage":{"title":"Seasons","genre":"poem","paras":["In summer, sunshine burns the sand,","And palm trees fan the thirsty land.","","In winter, cool winds softly blow,","And desert flowers start to grow.","","Each season brings a gift to share,","A different sky, a different air."],"poem":true},"items":[{"n":16,"t":"mc","s":"What happens in summer, according to the poem?","o":["Flowers start to grow.","Sunshine burns the sand.","It snows.","Cool winds softly blow."],"k":"B","sk":"Locates details in poetry","b":"171–180","g":"LT"},{"n":17,"t":"mc","s":"What does the poem describe in the first stanza?","o":["a rainy night","a cold winter","a windy spring","a hot summer"],"k":"D","sk":"Analyzes how specific parts of a poem contribute to meaning","b":"181–190","g":"LT"},{"n":18,"t":"mc","s":"What happens in winter, according to the poem?","o":["It snows every day.","Sunshine burns the sand all day.","Desert flowers start to grow.","Palm trees fall down."],"k":"C","sk":"Locates details in poetry","b":"181–190","g":"LT"},{"n":19,"t":"mc","s":"“Palm trees fan the thirsty land.” What does this mean?","o":["People sell paper fans under the palm trees.","The palm leaves move like fans over the dry land.","The trees are drinking water from the land.","The land is wet."],"k":"B","sk":"Interprets personification in context","b":"191–200","g":"LT"},{"n":20,"t":"mc","s":"What is the main message of the poem?","o":["Every season has something special.","Summer is the best season of the year.","Winter is too cold.","Flowers grow only in summer."],"k":"A","sk":"Determines theme in poetry","b":"191–200","g":"LT"}]},{"passage":{"title":"Where Does Rain Come From?","genre":"informational","paras":["The sun heats water in the sea, in lakes and in rivers. The warm water turns into a gas called water vapor and rises into the sky.","High in the sky, the air is cold. The water vapor cools and changes into tiny drops. Many drops together make a cloud.","When the drops in a cloud join and become heavy, they fall to the ground as rain. Then the water flows back to the sea, and it all happens again. This is called the **water cycle**."]},"items":[{"n":21,"t":"mc","s":"What makes the water rise into the sky?","o":["Rain falls on it.","Clouds pull it up.","The wind pushes it.","The sun heats it."],"k":"D","sk":"Determines the cause of a situation","b":"181–190","g":"IT"},{"n":22,"t":"mc","s":"What happens to water vapor when it gets cold?","o":["It becomes a river.","It changes into tiny drops.","It disappears forever into the sky.","It turns into the sun."],"k":"B","sk":"Understands sequence in informational text","b":"181–190","g":"IT"},{"n":23,"t":"mc","s":"Which step comes LAST in the text?","o":["Drops make a cloud.","Water vapor rises.","The water flows back to the sea.","The sun heats the water in the sea."],"k":"C","sk":"Identifies process as a structure","b":"181–190","g":"IT"},{"n":24,"t":"mc","s":"What is water vapor?","o":["a gas made from warm water","a river","a kind of cold rain","a kind of white cloud in the sky"],"k":"A","sk":"Determines domain-specific word meaning in context","b":"181–190","g":"IT"},{"n":25,"t":"mc","s":"Why is it called a **cycle**?","o":["It is very fast.","It has two wheels, like a bicycle.","It happens again and again in a circle.","It happens only once in a long time."],"k":"C","sk":"Determines the meaning of domain-specific words","b":"191–200","g":"IT"}]},{"passage":{"title":"A Surprise for the Teacher","genre":"story","paras":["Mr. Adel was leaving the school to work in another city. On his last day, the students of Class 3B wanted to say goodbye in a special way.","Each boy wrote one sentence about something Mr. Adel had taught him. Ammar wrote, “You taught me that mistakes help us learn.” Jassim wrote, “You taught me to love reading.” Then they put all the sentences into one big card.","When Mr. Adel read the card, he was quiet for a long moment. Then he said softly, “This card is the best lesson you have taught me.”"]},"items":[{"n":26,"t":"mc","s":"Why do the students make a card?","o":["Mr. Adel is leaving the school.","It is Mr. Adel’s birthday this week.","Mr. Adel is sick.","They want to win a prize."],"k":"A","sk":"Determines the cause of a situation","b":"171–180","g":"LT"},{"n":27,"t":"mc","s":"What did each boy write?","o":["a poem about the city where he lives with his family","one sentence about something Mr. Adel taught him","a long story about the school","his name only"],"k":"B","sk":"Locates details about plot","b":"171–180","g":"LT"},{"n":28,"t":"mc","s":"“He was quiet for a long moment.” What does this show?","o":["Mr. Adel was asleep.","Mr. Adel was angry about what the card said.","Mr. Adel could not read the words.","Mr. Adel was deeply touched by the card."],"k":"D","sk":"Determines details that reveal characters’ feelings","b":"191–200","g":"LT"},{"n":29,"t":"mc","s":"What does Mr. Adel mean when he says the card is “the best lesson you have taught me”?","o":["The students are better teachers than he is now.","The students taught him how much his work mattered.","He did not like the card.","He wants to give them homework."],"k":"B","sk":"Determines the meaning of a nonliteral phrase","b":"191–200","g":"LT"},{"n":30,"t":"mc","s":"What is the theme of the story?","o":["Showing thanks can mean a lot to others.","Writing is difficult.","Cards are always better than gifts.","Teachers should never move to new cities."],"k":"A","sk":"Determines theme in literary text","b":"191–200","g":"LT"}]},{"passage":null,"items":[{"n":31,"t":"mc","s":"Read the sentence. “The puppy was **curious** and sniffed every corner of the room.” What does **curious** mean?","o":["very sleepy all day long","very quiet","wanting to find out about things","afraid of everything around it"],"k":"C","sk":"Uses context to determine word meaning","b":"181–190","g":"VO"},{"n":32,"t":"mc","s":"Which word means “not honest”?","o":["honestful","rehonest","honestless","dishonest"],"k":"D","sk":"Understands how the prefix dis- changes meaning","b":"181–190","g":"VO"},{"n":33,"t":"mc","s":"The root **graph** means “write.” Which word means “something you write”?","o":["telephone","football","paragraph","bicycle"],"k":"C","sk":"Applies knowledge of Greek or Latin roots","b":"181–190","g":"VO"},{"n":34,"t":"mc","s":"“I could eat a horse!” What does the speaker mean?","o":["I am full.","I like horses.","I am very strong.","I am very hungry."],"k":"D","sk":"Understands the meaning of common idioms","b":"181–190","g":"VO"},{"n":35,"t":"mc","s":"Read the sentence. “Can you **park** the car near the **park**?” What is the SECOND **park**?","o":["a kind of small car for children","a green place where people play","a ticket for parking a car","to stop a car"],"k":"B","sk":"Determines which meaning of a multiple-meaning word fits","b":"181–190","g":"VO"},{"n":36,"t":"mc","s":"Read the sentence. “The old man was **wise**; he always gave good advice.” What does **wise** mean?","o":["having good sense","very young and small","very rich","very tired"],"k":"A","sk":"Uses context to determine word meaning","b":"181–190","g":"VO"},{"n":37,"t":"mc","s":"Which word means “to spell wrongly”?","o":["spellful","unspell","misspell","respell"],"k":"C","sk":"Understands how the prefix mis- changes meaning","b":"181–190","g":"VO"},{"n":38,"t":"mc","s":"Which word BEST completes the sentence? “I like apples, ___ I do not like bananas.”","o":["because","so","and then","but"],"k":"D","sk":"Words that show a contrast","b":"181–190","g":"VO"},{"n":39,"t":"mc","s":"Which word means the OPPOSITE of **ancient**?","o":["old","modern","broken","large"],"k":"B","sk":"Identifies antonyms","b":"191–200","g":"VO"},{"n":40,"t":"mc","s":"Which word BEST completes the sentence? “The box was too heavy, ___ I asked my father for help.”","o":["so","but","or","because"],"k":"A","sk":"Understands words that show cause and effect","b":"191–200","g":"VO"},{"n":41,"t":"mc","s":"A **player** is a person who plays. A **singer** is a person who —","o":["sings again","sings","is sung to","cannot sing"],"k":"B","sk":"Understands how the suffix -er changes the meaning of a noun","b":"191–200","g":"VO"},{"n":42,"t":"mc","s":"Which word has the root **tele**, meaning “far”?","o":["table","tell","telephone","teacher"],"k":"C","sk":"Applies knowledge of Greek or Latin roots","b":"191–200","g":"VO"},{"n":43,"t":"mc","s":"“The wind **whispered** through the trees.” What does this tell you about the wind?","o":["It was very cold.","It was talking to people.","It was very loud.","It was soft and gentle."],"k":"D","sk":"Interprets personification in context","b":"191–200","g":"VO"}]}]}]};
